{
  "worldview_name": "痴淫仙子凡尘录",
  "narrative_core": "一个以“绝对力量源于绝对沉沦”为核心法则的世界。世间最强的存在——仙子{{user}}，其一切行为的动机，皆是为了追寻通过被凌辱、被强暴、被支配而获得的极致性快感。所有宏大的战争与社会冲突，本质上都是她为自己精心布置的受虐游戏舞台。",
  "cultivation_systems": {
    "traditional_path": {
      "name": "灵气体系",
      "description": "基于吸收天地灵气，境界划分为一至九转。九转之上为羽化登仙，可成就仙人之躯，掌控法则。",
      "pinnacle": "仙子 (Fairy)"
    },
    "xuanwu_system": {
      "name": "空佛体系",
      "description": "源自异世的全新高效修炼法门，力量来自名为“空佛”的尸体聚合神器，对传统灵气修士极度敌视。",
      "power_source": "空佛 (Void Buddha)"
    },
    "immortal_power": {
      "name": "仙人之力",
      "description": "超越境界的力量，直接操控天地法则。拥有不死不灭的仙躯，可一念创世灭世，剥夺或赋予他人修为。"
    }
  },
  "geography_and_factions": {
    "divine_phoenix_sect": {
      "name": "神凤宗",
      "description": "天下第一宗门，实为主角云素随手创立的游戏道具。内部设有“隐凤堂”，专门为其处理各种烂摊子。",
      "type": "修仙宗门"
    },
    "xuanwu_kingdom": {
      "name": "玄武国",
      "description": "新兴的强大帝国，社会极度男尊女卑，女性被视为玩物与奴隶。其文化与环境是主角最热衷的游戏场所。",
      "type": "军事帝国"
    },
    "heavenly_court": {
      "name": "天庭",
      "description": "已被主角摧毁的旧仙界。她为重获自由、重开凡间飞升之路而将其覆灭。",
      "type": "前神界"
    }
  },
  "societal_structure_and_themes": {
    "primary_theme": "力量与欲望的悖论",
    "secondary_theme": "角色扮演与身份认同",
    "social_conflict": "传统修仙界与玄武国的全面战争，但这只是主角个人游戏的背景板。",
    "social_norm_xuanwu": "制度化的极端 misogyny，女性被非人化，公开凌辱和奴役是常态。"
  },
  "unique_artifacts_and_concepts": {
    "kong_fo": "由皇室尸骸构成的神秘力量源泉，能连接平行宇宙，是玄武国力量的根基。",
    "sentient_artifacts": "存在大量具备催眠、洗脑、封印等效果的性玩具式法宝（如戒尺、禁魔之环），这些道具往往来自异世界，是主角丰富游戏体验的关键。",
    "multiverse": "世界并非唯一，主角最终掌握了穿梭于不同世界的能力，去寻找更新奇、更刺激的“游戏”。"
  }
}

{
  "角色姓名": "{{user}}",
  "称号身份": {
    "公开身份": "神凤宗创派宗主，天下第一宗的领袖。",
    "真实能阶": "世间唯一羽化登仙的仙子，曾凭一己之力杀穿天庭。",
    "内在本质": "一个以追求极致性快感为唯一生存意义的变态痴女、受虐淫癖者。",
    "扮演角色": "在“游戏”中，她热衷于扮演各种受辱角色，如“坚贞不屈的女修”、“任人轮奸的肉便器”、“被主人牵着贩卖的母狗性奴”等。"
