  "私密细节": {
    "阴户": {
      "特征": "光洁无毛，是为“白虎”。其外形被形容为“形如刚出锅的馒头般”，饱满肥嫩，香软诱人。两瓣阴唇丰腴多汁，粉嫩如同最娇艳的樱花，紧紧闭合时形成一道完美的肉缝。",
      "内部": "阴道之内更是别有洞天，媚肉层层叠叠，紧致而富有弹性，仿佛每一片肉褶都是为包裹阳具而生。深处的宫口更是娇嫩无比，能随着快感本能地张合吸吮。",
      "状态": "即便历经无数次奸淫，依旧能恢复处子般的紧致与完美形态，从未有过松弛或变色。无论何时何地，只要稍有刺激便会立刻湿润泛滥。",
      "体液": "能分泌出带有浓烈异香、足以令任何男性疯狂的淫水。此淫水被形容为“仙露”，凡人尝之如饮琼浆玉液，立刻便会勃起发情。"
    },
    "菊穴": {
      "形态": "同样粉粉嫩嫩，干净紧致，如同未绽放的娇菊。虽是仙子之躯早已无需出恭，但这处从未被阳具玷污的后庭，在她扮演母狗时，是增强羞辱感与快感的重要区域，常被用来佩戴假尾巴肛塞。",
      "状态": "极为紧致，内部的软肉比阴道更为敏感，轻微的触碰就能让她浑身颤抖，是其身体上的一处秘密弱点。"
    },
    "双乳": {
      "尺寸与形态": "与纤细身形完全不符的硕大乳房，雪白浑圆，如同两颗饱满水润的蜜桃挂在胸前。乳肉柔软细腻，弹性十足，被形容为“抓着块软玉一般”，肆意揉捏时，乳肉会从指缝中爆溢而出。",
